CREATE OR REPLACE FUNCTION public.approve_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_admin_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_claim RECORD; v_admin_role text; v_previous_owner uuid;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_admin_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;

    -- Only admins can approve
    SELECT role INTO v_admin_role FROM profiles WHERE id = p_admin_user_id;
    IF v_admin_role IS NULL OR v_admin_role NOT IN ('admin','superadmin','moderator') THEN
        RAISE EXCEPTION 'NOT_ADMIN';
    END IF;

    SELECT id, venue_id, user_id, status INTO v_claim FROM venue_claims
     WHERE id = p_claim_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_NOT_FOUND'; END IF;
    IF v_claim.status NOT IN ('pending','under_review') THEN
        RAISE EXCEPTION 'CLAIM_NOT_ACTIONABLE';
    END IF;

    -- Check if venue already claimed by someone else
    SELECT claimed_by INTO v_previous_owner FROM poker_venues WHERE id = v_claim.venue_id;
    IF v_previous_owner IS NOT NULL AND v_previous_owner <> v_claim.user_id THEN
        RAISE EXCEPTION 'VENUE_ALREADY_CLAIMED_BY_ANOTHER';
    END IF;

    -- Update claim
    UPDATE venue_claims 
       SET status = 'approved', verified_at = now(), 
           verified_by = p_admin_user_id,
           admin_notes = COALESCE(p_admin_notes, admin_notes),
           updated_at = now()
     WHERE id = p_claim_id;

    -- Flip the venue to claimed - this fires trg_venue_claim_wiring which:
    --   (a) auto-creates social_page, and
    --   (b) sets commander_enabled=true
    UPDATE poker_venues
       SET is_claimed = true,
           claimed_by = v_claim.user_id,
           claimed_at = COALESCE(claimed_at, now())
     WHERE id = v_claim.venue_id;

    -- Add claimant as the venue's primary manager
    INSERT INTO venue_managers (
        venue_id, user_id, role,
        can_edit_info, can_edit_hours, can_edit_games, can_post_updates,
        can_respond_reviews, can_manage_promotions, can_view_analytics, can_invite_staff,
        is_active, invited_by
    ) VALUES (
        v_claim.venue_id, v_claim.user_id, 'owner',
        true, true, true, true, true, true, true, true, true, p_admin_user_id
    ) ON CONFLICT DO NOTHING;

    -- Dismiss other pending claims for the same venue
    UPDATE venue_claims
       SET status = 'rejected',
           rejection_reason = 'Another claim was approved first',
           updated_at = now()
     WHERE venue_id = v_claim.venue_id AND id <> p_claim_id 
       AND status IN ('pending','under_review');

    RETURN jsonb_build_object(
        'success', true, 'claim_id', p_claim_id, 'venue_id', v_claim.venue_id,
        'new_owner_id', v_claim.user_id,
        'commander_enabled', true, 'social_page_auto_provisioned', true
    );
END; $function$

CREATE OR REPLACE FUNCTION public.fn_ensure_social_page_for_venue(p_venue_id integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_existing_id uuid; v_venue RECORD; v_new_id uuid; v_cover text;
BEGIN
    SELECT id INTO v_existing_id FROM social_pages
     WHERE linked_entity_type = 'venue' AND linked_entity_id = p_venue_id::text
     LIMIT 1;
    IF v_existing_id IS NOT NULL THEN RETURN v_existing_id; END IF;

    SELECT id, name, tagline, about, city, state, country, phone, website,
           is_claimed, claimed_by, venue_type
      INTO v_venue FROM poker_venues WHERE id = p_venue_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    SELECT url INTO v_cover FROM commander_venue_photos
     WHERE venue_id = p_venue_id AND is_cover_photo = true LIMIT 1;

    INSERT INTO social_pages (
        owner_id, page_type, name, description, cover_url, category,
        website, phone, location_city, location_state, location_country,
        linked_entity_type, linked_entity_id, linked_venue_id,
        is_public, metadata
    ) VALUES (
        v_venue.claimed_by, 'venue', v_venue.name,
        COALESCE(v_venue.tagline, v_venue.about),
        v_cover, 'poker',
        v_venue.website, v_venue.phone,
        v_venue.city, v_venue.state, COALESCE(v_venue.country, 'US'),
        'venue', v_venue.id::text, v_venue.id::text,
        true,
        jsonb_build_object('auto_provisioned', true, 'source', 'phase29',
                           'at', now(), 'is_claimed', v_venue.is_claimed)
    ) RETURNING id INTO v_new_id;
    RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_ensure_social_page_for_venue failed for %: %', p_venue_id, SQLERRM;
    RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.resolve_venue_location_integrity(p_venue_id integer, p_expected_updated_at timestamp with time zone, p_address text, p_city text, p_state text, p_latitude double precision, p_longitude double precision, p_reason text, p_actor_id uuid, p_integrity_status text, p_integrity_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_before public.poker_venues%ROWTYPE;
  v_after public.poker_venues%ROWTYPE;
  v_actor_role text;
BEGIN
  SELECT p.role::text INTO v_actor_role
  FROM public.profiles p
  WHERE p.id = p_actor_id;

  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'superadmin', 'god') THEN
    RAISE EXCEPTION 'platform admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'expected venue revision required' USING ERRCODE = '22023';
  END IF;
  IF char_length(trim(coalesce(p_reason, ''))) < 12 OR char_length(trim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'audit reason must contain 12 to 500 characters' USING ERRCODE = '22023';
  END IF;
  IF p_integrity_status NOT IN ('verified', 'border') THEN
    RAISE EXCEPTION 'only verified or border corrections may be applied' USING ERRCODE = '22023';
  END IF;
  IF p_latitude IS NULL OR p_longitude IS NULL
     OR p_latitude < -90 OR p_latitude > 90
     OR p_longitude < -180 OR p_longitude > 180 THEN
    RAISE EXCEPTION 'coordinates outside valid range' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_before
  FROM public.poker_venues
  WHERE id = p_venue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'venue not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_before.location_integrity_revision IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'venue revision changed' USING ERRCODE = '40001';
  END IF;

  UPDATE public.poker_venues
  SET address = nullif(trim(p_address), ''),
      city = trim(p_city),
      state = upper(trim(p_state)),
      latitude = p_latitude,
      longitude = p_longitude,
      lat = p_latitude,
      lng = p_longitude,
      last_verified_at = now(),
      location_integrity_revision = clock_timestamp()
  WHERE id = p_venue_id
  RETURNING * INTO v_after;

  INSERT INTO public.venue_location_integrity_log (
    venue_id,
    actor_id,
    reason,
    integrity_status,
    integrity_reason,
    before_record,
    after_record
  ) VALUES (
    p_venue_id,
    p_actor_id,
    trim(p_reason),
    p_integrity_status,
    p_integrity_reason,
    jsonb_build_object(
      'address', v_before.address,
      'city', v_before.city,
      'state', v_before.state,
      'latitude', coalesce(v_before.latitude, v_before.lat),
      'longitude', coalesce(v_before.longitude, v_before.lng),
      'location_integrity_revision', v_before.location_integrity_revision
    ),
    jsonb_build_object(
      'address', v_after.address,
      'city', v_after.city,
      'state', v_after.state,
      'latitude', coalesce(v_after.latitude, v_after.lat),
      'longitude', coalesce(v_after.longitude, v_after.lng),
      'location_integrity_revision', v_after.location_integrity_revision
    )
  );

  RETURN jsonb_build_object(
    'venue_id', v_after.id,
    'name', v_after.name,
    'location_integrity_revision', v_after.location_integrity_revision,
    'integrity_status', p_integrity_status
  );
END;
$function$

